#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
using i128 = __int128_t;

i128 mult(i128 a, i128 b) {
    return a * b;
}

int64 count_suitable(int64 X) {
    if (X < 5) return 0;
    i128 x = X;

    // k_max = floor(sqrt(2X + 1))
    int64 k_max = sqrt((long double)(2.0 * X + 1.0));
    while ((i128)(k_max + 1) * (k_max + 1) <= 2 * x + 1) k_max++;
    while ((i128)k_max * k_max > 2 * x + 1) k_max--;

    int64 total = 0;
    for (int64 k = 1; k <= k_max; k += 2) {
        i128 k2 = (i128)k * k;
        i128 num = mult(2, x) - k2 + 1;
        if (num <= 0) continue;
        i128 den = mult(2, k);
        int64 m_max = (int64)(num / den);
        if (m_max > k - 1) m_max = k - 1;
        if (m_max < 1) continue;
        // count odd m in [1, m_max]
        int64 cnt = (m_max + 1) / 2;
        total += cnt;
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 N;
    if (!(cin >> N)) return 0;

    int64 lo = 5, hi = 2000000000000000000LL; // 2e18 upper bound
    while (lo < hi) {
        int64 mid = lo + (hi - lo) / 2;
        if (count_suitable(mid) >= N)
            hi = mid;
        else
            lo = mid + 1;
    }
    cout << lo << "\n";
    return 0;
}
