        if (x < 3) return 0;
        __int128 val = (__int128)x * x + 8;
        long long s = sqrt((long double)val);
        while ((__int128)(s + 1) * (s + 1) <= val) ++s;
        while ((__int128)s * s > val) --s;
        return (s - 1) / 2;
    };

    long long low = 1, high = 2000000000LL;
    while (low < high) {
        long long mid = low + (high - low) / 2;
        if (f(mid) >= N)
            high = mid;
        else
            low = mid + 1;
    }
    cout << low << "\n";
    return 0;
}
