#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

bool check(int64 x, int64 N) {
    // Count suitable numbers <= x
    // Count_even = number of a (2 <= a <= floor(sqrt(x)))
    int64 a_max = sqrt((long double)x);
    while ((i128)(a_max + 1) * (a_max + 1) <= x) ++a_max;
    while ((i128)a_max * a_max > x) --a_max;
    int64 count_even = 0;
    if (a_max >= 2) count_even = a_max - 1;

    // Count_odd = number of d (d odd, d >= 3) such that d*(d+2) <= x
    // d^2 + 2d - x <= 0 => d <= -1 + sqrt(1+x)
    int64 d_max = sqrt((long double)(x + 1)) - 1;
    while ((i128)(d_max + 1) * (d_max + 3) <= x) ++d_max;
    while ((i128)d_max * (d_max + 2) > x) --d_max;
    int64 count_odd = 0;
    if (d_max >= 3) {
        // Number of odd integers in [3, d_max]
        count_odd = (d_max + 1) / 2 - 1;
    }

    // Check for overflow
    i128 total = (i128)count_even + count_odd;
    return total >= N;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 N;
    cin >> N;

    int64 low = 0;
    int64 high = 3000000000LL; // 3e9 is safe upper bound for answer when N=1e9
    // Approximately: count ~ sqrt(x) + sqrt(x)/2 = 1.5*sqrt(x) => x ~ (N/1.5)^2 ~ 4.44e17 sqrt is 6e8.
    // 3e9 is plenty.

    while (low < high) {
        int64 mid = low + (high - low) / 2;
        if (check(mid, N)) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }

    cout << low << "\n";
    return 0;
}
